module top_module (
    input clk,
    input aresetn,
    input x,
    output reg z
);

    localparam [1:0] S   = 2'd0;
    localparam [1:0] S1  = 2'd1;
    localparam [1:0] S10 = 2'd2;

    reg [1:0] state, next_state;

    always @(posedge clk or negedge aresetn) begin
        if (~aresetn) begin
            state <= S;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            S: begin
                if (x == 1'b0) begin
                    next_state = S;
                end else begin
                    next_state = S1;
                end
                z = 1'b0;
            end

            S1: begin
                if (x == 1'b0) begin
                    next_state = S10;
                end else begin
                    next_state = S1;
                end
                z = 1'b0;
            end

            S10: begin
                if (x == 1'b0) begin
                    next_state = S;
                end else begin
                    next_state = S1;
                end
                z = x;
            end

            default: begin
                next_state = S;
                z = 1'b0;
            end
        endcase
    end

endmodule
